using System;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Input;

namespace IRI.Maptor.Presentation.Wpf.Helpers;

/// <summary>
/// The Maptor map cursor set. The .cur files under Assets/Cursors/MaptorCursorSet are generated by
/// tools/CursorGenerator (one image per size: 32, 40, 48 and 64 px); edit the generator, not the files.
/// </summary>
public static class MapCursorHelper
{
    private const string BaseUri = "/IRI.Maptor.Presentation.Wpf;component/Assets/Cursors/MaptorCursorSet/";

    /// <summary>
    /// Loads a cursor of the set. Scaled with the screen DPI: Windows picks the image that matches the
    /// system cursor size (32 px at 100 %, 48 px at 150 %, ...).
    /// </summary>
    public static Cursor Load(string fileName)
    {
        var stream = Application.GetResourceStream(new Uri(BaseUri + fileName, UriKind.Relative))?.Stream
            ?? throw new InvalidOperationException($"Cursor resource not found: {fileName}");

        return new Cursor(stream, true);
    }

    public static IReadOnlyDictionary<MapAction, Cursor> CreateDefaultSet()
    {
        return new Dictionary<MapAction, Cursor>
        {
            { MapAction.Pan, Load("Pan.cur") },
            { MapAction.ZoomIn, Load("ZoomIn.cur") },
            { MapAction.ZoomInRectangle, Load("ZoomIn.cur") },
            { MapAction.ZoomOut, Load("ZoomOut.cur") },
            { MapAction.DrawPoint, Load("DrawPoint.cur") },
            { MapAction.DrawPolyline, Load("DrawPolyline.cur") },
            { MapAction.DrawPolygon, Load("DrawPolygon.cur") },
            { MapAction.DrawRectangle, Load("DrawRectangle.cur") },
            { MapAction.Identify, Load("information.cur") },
            { MapAction.DrawText, Load("DrawText.cur") },
            { MapAction.None, Cursors.Arrow },
        };
    }

    /// <summary>Cursors for the states that are not a <see cref="MapAction"/>.</summary>
    public static IReadOnlyDictionary<MapExtraCursor, Cursor> CreateDefaultExtraSet()
    {
        return new Dictionary<MapExtraCursor, Cursor>
        {
            { MapExtraCursor.PanDragging, Load("PanGrabbing.cur") },
            { MapExtraCursor.MeasureLength, Load("MeasureLength.cur") },
            { MapExtraCursor.MeasureArea, Load("MeasureArea.cur") },
        };
    }
}
